import mongoose, { Schema, Document } from "mongoose";

// One auto-generated lecture attendance session per
// (class, course, subject, lecturer, date). Created at 75% of the lecture
// duration by the daily scheduler; carries window + venue + lecturer
// check-in metadata that the per-student attendance records reference.

export type LectureSessionStatus =
  | "generated"
  | "open"
  | "closed"
  | "resolved";

export interface ILectureSession extends Document {
  class: mongoose.Types.ObjectId;
  course: mongoose.Types.ObjectId;
  subject: mongoose.Types.ObjectId | null;
  lecturer: mongoose.Types.ObjectId | null;
  academicYear: mongoose.Types.ObjectId;
  date: Date;
  dayOfWeek: string;
  source: "lecture";
  autoGenerated: boolean;

  venue: mongoose.Types.ObjectId | null;
  venueSnapshot: {
    name: string;
    room: string;
    lat: number;
    lng: number;
    radiusMeters: number;
  };

  // Attendance window (D1): opens at 75% of lecture duration, closes at
  // lecture end + 5 minutes grace.
  window: {
    lectureStart: Date;
    lectureEnd: Date;
    triggerAt: Date;
    openedAt: Date | null;
    closesAt: Date;
  };

  // Lecturer GPS check-in (D5): fallback unverified if missing.
  lecturerCheckIn: {
    lat: number | null;
    lng: number | null;
    at: Date | null;
    verified: boolean;
  };

  status: LectureSessionStatus;
  escalation: {
    escalatedToAdmin: boolean;
    escalatedAt: Date | null;
  };
  createdBy: mongoose.Types.ObjectId | null;
}

const lectureSessionSchema = new Schema<ILectureSession>(
  {
    class: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Class",
      required: true,
    },
    course: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Course",
      required: true,
    },
    subject: {
      type: mongoose.Schema.Types.ObjectId,
      default: null,
    },
    lecturer: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      default: null,
    },
    academicYear: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "AcademicYear",
      required: true,
    },
    date: {
      type: Date,
      required: true,
    },
    dayOfWeek: {
      type: String,
      required: true,
    },
    source: {
      type: String,
      enum: ["lecture"],
      default: "lecture",
    },
    autoGenerated: {
      type: Boolean,
      default: true,
    },
    venue: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Venue",
      default: null,
    },
    venueSnapshot: {
      name: { type: String, default: "" },
      room: { type: String, default: "" },
      lat: { type: Number, default: 0 },
      lng: { type: Number, default: 0 },
      radiusMeters: { type: Number, default: 150 },
    },
    window: {
      lectureStart: { type: Date, default: null },
      lectureEnd: { type: Date, default: null },
      triggerAt: { type: Date, default: null },
      openedAt: { type: Date, default: null },
      closesAt: { type: Date, default: null },
    },
    lecturerCheckIn: {
      lat: { type: Number, default: null },
      lng: { type: Number, default: null },
      at: { type: Date, default: null },
      verified: { type: Boolean, default: false },
    },
    status: {
      type: String,
      enum: ["generated", "open", "closed", "resolved"],
      default: "generated",
    },
    escalation: {
      escalatedToAdmin: { type: Boolean, default: false },
      escalatedAt: { type: Date, default: null },
    },
    createdBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      default: null,
    },
  },
  { timestamps: true }
);

// One auto-generated session per class+course+subject+lecturer+date
lectureSessionSchema.index(
  {
    class: 1,
    course: 1,
    subject: 1,
    lecturer: 1,
    date: 1,
  },
  { unique: true }
);
lectureSessionSchema.index({ date: 1, status: 1 });

export default mongoose.model<ILectureSession>(
  "LectureSession",
  lectureSessionSchema
);
